import math


def count_Odd_Squares(n, m):
    """Write a python function to find number of elements with odd factors in a given range."""
    # A positive integer has an odd number of factors iff it is a perfect
    # square: factors occur in pairs except for the repeated square root.
    # So count perfect squares in the inclusive integer range [n, m].
    lo = math.ceil(n)
    hi = math.floor(m)
    if hi < lo or hi < 1:
        return 0
    lo = max(lo, 1)
    return math.isqrt(hi) - math.isqrt(lo - 1)
